CREATE DATABASE IF NOT EXISTS dongxiang CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE dongxiang;
CREATE TABLE IF NOT EXISTS app_user (id BIGINT PRIMARY KEY AUTO_INCREMENT, phone VARCHAR(11) NOT NULL UNIQUE, nickname VARCHAR(64) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS venue (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL, city VARCHAR(64) NOT NULL, address VARCHAR(255) NOT NULL, category VARCHAR(64) NOT NULL, description TEXT);
CREATE TABLE IF NOT EXISTS post (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, venue_id BIGINT NOT NULL, title VARCHAR(120) NOT NULL, content TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES app_user(id), FOREIGN KEY(venue_id) REFERENCES venue(id));
CREATE TABLE IF NOT EXISTS post_like (post_id BIGINT NOT NULL, user_id BIGINT NOT NULL, PRIMARY KEY(post_id,user_id), FOREIGN KEY(post_id) REFERENCES post(id), FOREIGN KEY(user_id) REFERENCES app_user(id));
CREATE TABLE IF NOT EXISTS post_comment (id BIGINT PRIMARY KEY AUTO_INCREMENT, post_id BIGINT NOT NULL, user_id BIGINT NOT NULL, content VARCHAR(1000) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(post_id) REFERENCES post(id), FOREIGN KEY(user_id) REFERENCES app_user(id));
CREATE TABLE IF NOT EXISTS voucher (id BIGINT PRIMARY KEY AUTO_INCREMENT, venue_id BIGINT NOT NULL, title VARCHAR(120) NOT NULL, price_cents INT NOT NULL, stock INT NOT NULL, start_at DATETIME NOT NULL, end_at DATETIME NOT NULL, FOREIGN KEY(venue_id) REFERENCES venue(id));
CREATE TABLE IF NOT EXISTS voucher_order (id CHAR(32) PRIMARY KEY, voucher_id BIGINT NOT NULL, user_id BIGINT NOT NULL, status VARCHAR(16) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, expires_at DATETIME NOT NULL, UNIQUE KEY uq_order_user_voucher(voucher_id,user_id), INDEX idx_order_expiry(status,expires_at), FOREIGN KEY(voucher_id) REFERENCES voucher(id), FOREIGN KEY(user_id) REFERENCES app_user(id));
CREATE TABLE IF NOT EXISTS stock_release (order_id CHAR(32) PRIMARY KEY, voucher_id BIGINT NOT NULL, user_id BIGINT NOT NULL, processed BOOLEAN NOT NULL DEFAULT FALSE, INDEX idx_release_processed(processed), FOREIGN KEY(order_id) REFERENCES voucher_order(id));
